import type { Level, RiskTotals, Column } from './types';
export type { Level, RiskTotals, Column };

/**
 * Карточка одного показателя: крупное значение и подпись под ним. Цвет рамки задаёт `level`; без него карточка серая.
 * Несколько карточек кладут подряд внутрь контейнера с классом `kpis`.
 */
export function Kpi(props: {
  /** Крупное значение, уже отформатированное: «15,6 мкЗв», «0,858 случая на 1 млн». */
  value: string;
  /** Подпись, что это за величина. */
  label: string;
  /** Уровень относительно нормы; влияет на цвет. */
  level?: Level;
}): JSX.Element;

/**
 * Блок «Дополнительные случаи рака за всю жизнь»: главное число «N случаев на 1 млн человек», рост вероятности в процентах,
 * логарифмическая шкала риска с отметками уровней и ссылка на источник уровней. Без рамки — рамку даёт `RiskBox`.
 */
export function RiskBlock(props: {
  totals: RiskTotals;
  /** Сколько лет потребляется продукт; при значении больше 1 показываются две точки на шкале. */
  years: number;
}): JSX.Element;

/** Блок риска в цветной рамке по уровню НРБ-99/2009 (зелёная / жёлтая / красная). Используйте его, а не голый `RiskBlock`. */
export function RiskBox(props: { totals: RiskTotals; years: number }): JSX.Element;

/** Таблица расчёта: заголовки из `cols`, строки из `rows`; при пустом `rows` ничего не выводит. Прокручивается по горизонтали на узком экране. */
export function DataTable<R = any>(props: { rows: R[]; cols: Column<R>[] }): JSX.Element | null;
